insert into public.timelines (slug, owner_id, title, description, category, language, visibility, share_id, start_year, end_year, cover_seed)
values ('personal-gardening', '00000000-0000-4000-8000-282ed1c0bc89', 'ガーデニング日記', '1990年の花博で一鉢の花を買ってから36年。ベランダから仮設住宅の花壇、貸し農園、庭へ。育てる記録に暮らしの節目と花と緑をめぐる社会の動きを重ねた、私の庭と暮らしの日記です。', 'personal-life', 'ja', 'public', 's_personal-gardening', 1990, 2026, 'personal-gardening')
